{"patches":[{"old":"  if(steps>0){ for(const k in pressed) delete pressed[k]; }
  if(acc>STEP*6) acc=0;

  // 全局按键
  if(pressed['Enter']){
    if(!state.playing) startGame();
  }
  if(pressed['KeyR']&&state.started){
    startGame();
  }","new":"  // 全局按键先消费一次性按下，避免启动信号被帧清理吞掉
  if(pressed['Enter']){
    delete pressed['Enter'];
    if(!state.playing) startGame();
  }
  if(pressed['KeyR']){
    delete pressed['KeyR'];
    if(state.started) startGame();
  }
  if(steps>0){ for(const k in pressed) delete pressed[k]; }
  if(acc>STEP*6) acc=0;"}]}
